            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Liste-Alphab&#233;tique-Des-Objets-Merveilleux.html&quot; title=&quot;Liste alphab&#233;tique des objets merveilleux&quot;&gt;Liste alphab&#233;tique&lt;/a&gt;&lt;/li&gt;
            &lt;li style=&quot;max-width:150px&quot;&gt;Listes par emplacement : &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement.html&quot; title=&quot;Objets merveilleux sans emplacement&quot;&gt;aucun&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement-Liste.html&quot; title=&quot;Objets merveilleux sans emplacement liste&quot;&gt;avec profils&lt;/a&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Le-Corps.html&quot; title=&quot;Objets merveilleux port&#233;s sur le corps&quot;&gt;corps&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Autour-Du-Cou.html&quot; title=&quot;Objets merveilleux port&#233;s autour du cou&quot;&gt;cou&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Les-&#201;paules.html&quot; title=&quot;Objets merveilleux port&#233;s sur les &#233;paules&quot;&gt;&#233;paules&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Le-Front.html&quot; title=&quot;Objets merveilleux port&#233;s sur le front&quot;&gt;front&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Aux-Mains.html&quot; title=&quot;Objets merveilleux port&#233;s aux mains&quot;&gt;mains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Aux-Pieds.html&quot; title=&quot;Objets merveilleux port&#233;s aux pieds&quot;&gt;pieds&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Aux-Poignets.html&quot; title=&quot;Objets merveilleux port&#233;s aux poignets&quot;&gt;poignets&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-&#192;-La-Taille.html&quot; title=&quot;Objets merveilleux port&#233;s &#224; la taille&quot;&gt;taille&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-La-T&#234;te.html&quot; title=&quot;Objets merveilleux port&#233;s sur la t&#234;te&quot;&gt;t&#234;te&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Le-Torse.html&quot; title=&quot;Objets merveilleux port&#233;s sur le torse&quot;&gt;torse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Les-Yeux.html&quot; title=&quot;Objets merveilleux port&#233;s sur les yeux&quot;&gt;yeux&lt;/a&gt;.&lt;/li&gt;&lt;/ul&gt;
    &lt;/li&gt;
    &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Autels.html&quot; title=&quot;Les autels&quot;&gt;Les autels&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Implants-D&#233;moniaques.html&quot; title=&quot;Les implants d&#233;moniaques&quot;&gt;Les implants d&#233;moniaques&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Ioun.html&quot; title=&quot;Pierre ioun&quot;&gt;Les pierres ioun&lt;/a&gt;&lt;/li&gt;
