&lt;/div&gt;
Ces objets sont des brassards, des bracelets, des menottes, des fers, des canons d’avant-bras et tous les objets pouvant &#234;tre port&#233;s aux poignets.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; aux poignets &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets. &lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 0 g et 1,5 kg sauf les &lt;i&gt;Cha&#238;nes dimensionnelles&lt;/i&gt; qui p&#232;sent 2,5 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s aux poignets&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manches-&#192;-V&#234;tements.html&quot; title=&quot;Manches &#224; v&#234;tements&quot;&gt;Manches &#224; v&#234;tements&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut modifier l’apparence des v&#234;tements du porteur &#224; volont&#233; tant qu’il les porte.&lt;/td&gt;&lt;td&gt;200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-De-Lutteur.html&quot; title=&quot;Brassards de lutteur&quot;&gt;Brassards de lutteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +1 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#LUTTE&quot; title=&quot;Les manœuvres offensives&quot;&gt;lutte&lt;/a&gt; et aux tests effectu&#233;s pour briser d’une &#233;treinte.&lt;/td&gt;&lt;td&gt;500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Darmure.html&quot; title=&quot;Bracelets d&amp;#39;armure&quot;&gt;Bracelets d’armure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus d’armure &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, peuvent &#234;tre enchant&#233;s.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +1.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;| 4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +3.&lt;/td&gt;&lt;td&gt;| 9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +5.&lt;/td&gt;&lt;td&gt;| 25 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +7&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +7.&lt;/td&gt;&lt;td&gt;| 49 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +8&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +8.&lt;/td&gt;&lt;td&gt;| 64 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-De-Cambrioleur.html&quot; title=&quot;Brassards de cambrioleur&quot;&gt;Brassards de cambrioleur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peuvent se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Outils-De-Cambrioleur-(Objet).html&quot; title=&quot;Outils de cambrioleur&quot;&gt;outils de cambrioleur de qualit&#233; sup&#233;rieure&lt;/a&gt; &#224; volont&#233;. Une fois par jour, permettent de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#FAIRE10&quot; title=&quot;Les comp&#233;tences&quot;&gt;faire 10&lt;/a&gt; &#224; un test de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; m&#234;me en situation de stress.&lt;/td&gt;&lt;td&gt;1 050 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Dassiduit&#233;.html&quot; title=&quot;Bracelets d’assiduit&#233;&quot;&gt;Bracelets d’assiduit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lorsque le porteur &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#FAIRE10&quot; title=&quot;Les comp&#233;tences&quot;&gt;fait 20&lt;/a&gt; &#224; un test de comp&#233;tence, conf&#232;rent un bonus de comp&#233;tence de +5 &#224; ce test.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Menottes-De-Coop&#233;ration.html&quot; title=&quot;Menottes de coop&#233;ration&quot;&gt;Menottes de coop&#233;ration&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Enfil&#233;es &#224; une cr&#233;ature &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Sansd&#233;fense&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;sans d&#233;fense&lt;/a&gt;, la rend docile si elle rate un jet de sauvegarde.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelet-De-Vision.html&quot; title=&quot;Bracelet de vision&quot;&gt;Bracelet de vision&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;&lt;/i&gt;. Conf&#232;re un bonus de +1 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;N&#233;thys-(Technique).html&quot; title=&quot;N&#233;thys&quot;&gt;N&#233;thys&lt;/a&gt; peut utiliser cet objet comme un &lt;a class=&quot;pagelink&quot; href=&quot;Sceptre-De-M&#233;tamagie.html#Incantation silencieuse&quot; title=&quot;Sceptre de m&#233;tamagie&quot;&gt;sceptre de m&#233;tamagie mineur (incantation silencieuse)&lt;/a&gt; une fois par jour, et d&#233;penser ses emplacements de sort pour lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;2 100 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Menottes-Dob&#233;issance.html&quot; title=&quot;Menottes d’ob&#233;issance&quot;&gt;Menottes d’ob&#233;issance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Enfil&#233;es &#224; une cr&#233;ature, conf&#232;rent un bonus de +4 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; contre elle. Trois fois par jour, permet au possesseur des cl&#233;s de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Injonction.html&quot; title=&quot;Injonction&quot;&gt;injonction&lt;/a&gt;&lt;/i&gt; sur la cr&#233;ature menott&#233;e.&lt;/td&gt;&lt;td&gt;3 280 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-Du-Faucon-Chasseur.html&quot; title=&quot;Brassards du faucon chasseur&quot;&gt;Brassards du faucon chasseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peuvent conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspect-Du-Faucon.html&quot; title=&quot;Aspect du faucon&quot;&gt;aspect du faucon&lt;/a&gt;&lt;/i&gt; pendant 1 minute (sans modification physique).&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Canons-Fortifi&#233;s-Dinquisiteur.html&quot; title=&quot;Canons fortifi&#233;s d’inquisiteur&quot;&gt;Canons fortifi&#233;s d’inquisiteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;inquisiteur&lt;/a&gt; avec le &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#JUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;jugement&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Jugements.html#PROTECTION&quot; title=&quot;Les jugements d&amp;#39;inquisiteur&quot;&gt;de protection&lt;/a&gt; obtient un bonus de saintet&#233; au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; et aux tests pour &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts.html#INCANTATIONSURLADEFENSIVE&quot; title=&quot;Lancer des sorts&quot;&gt;incanter sur la d&#233;fensive&lt;/a&gt; &#233;gal au bonus de ce jugement tant que ce dernier est actif.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Darcher.html&quot; title=&quot;Bracelets d&amp;#39;archer&quot;&gt;Bracelets d’archer&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionnent comme des &lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Darcher.html&quot; title=&quot;Bracelets d&amp;#39;archer&quot;&gt;bracelets d’archer hors-pair&lt;/a&gt; mais ne conf&#232;rent qu’un bonus de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et aucun bonus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-Dincantation-D&#233;fensive.html&quot; title=&quot;Brassards d’incantation d&#233;fensive&quot;&gt;Brassards d’incantation d&#233;fensive&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de +2 aux tests de concentration pour &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts.html#INCANTATIONSURLADEFENSIVE&quot; title=&quot;Lancer des sorts&quot;&gt;incanter sur la d&#233;fensive&lt;/a&gt;. Trois fois par jour, lorsque le porteur effectue un tel test, il peut lancer 2 jets et conserver le meilleur r&#233;sultat.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fourreau-De-Volatilisation.html&quot; title=&quot;Fourreau de volatilisation&quot;&gt;Fourreau de volatilisation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut stocker une arme l&#233;g&#232;re, une baguette magique ou une munition ne pesant pas plus de 2,5kg. L’objet stock&#233; ne p&#232;se rien et peut &#234;tre d&#233;gain&#233; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;. Conf&#232;re un bonus de +4 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; oppos&#233;s aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; d’un individu fouillant le porteur &#224; la recherche d’une arme dans le fourreau.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelet-De-Vigne.html&quot; title=&quot;Bracelet de vigne&quot;&gt;Bracelet de vigne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html#ARMEDEJET&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;arme &#224; aspersion&lt;/a&gt; qui peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Enchev&#234;tr&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;enchev&#234;trer&lt;/a&gt; les cr&#233;atures dans la zone d’effet et leur infliger 1d4 points de d&#233;g&#226;ts.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-De-D&#233;fense.html&quot; title=&quot;Brassards de d&#233;fense&quot;&gt;Brassards de d&#233;fense&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de parade de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Une fois par jour, permettent au porteur d’annuler une attaque &#224; distance qui le cible (comme avec &lt;a class=&quot;pagelink&quot; href=&quot;Parade-De-Projectiles.html&quot; title=&quot;Parade de projectiles&quot;&gt;Parade de projectiles&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Broyeurs.html&quot; title=&quot;Bracelets broyeurs&quot;&gt;Bracelets broyeurs&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, lorsque le porteur r&#233;ussit une attaque au corps &#224; corps, peuvent infliger un &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;affaiblissement temporaire&lt;/a&gt; de -6 &#224; une caract&#233;ristique physique de la cible.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Hurlants.html&quot; title=&quot;Bracelets hurlants&quot;&gt;Bracelets hurlants&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut manifester les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;sespoir-Foudroyant.html&quot; title=&quot;D&#233;sespoir foudroyant&quot;&gt;d&#233;sespoir foudroyant&lt;/a&gt;&lt;/i&gt; (le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; augmente en fonction du nombre de cr&#233;atures affect&#233;es d’un &lt;a class=&quot;pagelink&quot; href=&quot;Scalde.html#CHANTDERAGE&quot; title=&quot;Le scalde&quot;&gt;chant de rage&lt;/a&gt; effectu&#233; par le porteur &#224; l’activation).&lt;/td&gt;&lt;td&gt;7 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-Dallonge.html&quot; title=&quot;Brassards d’allonge&quot;&gt;Brassards d’allonge&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peuvent augmenter l’allonge du porteur de 1,50m jusqu’au d&#233;but de son prochain tour (lui infligeant un malus de -4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;, sauf &#224; ceux des attaques &#224; mains nues et naturelles).&lt;/td&gt;&lt;td&gt;7 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-Damuseur.html&quot; title=&quot;Brassards d’amuseur&quot;&gt;Brassards d’amuseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt;. Une fois par jour, peuvent conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bagou.html&quot; title=&quot;Bagou&quot;&gt;bagou&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;7 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelet-De-Charmes.html&quot; title=&quot;Bracelet de charmes&quot;&gt;Bracelet de charmes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Contient 1d4+4 charmes non-magiques et 1 exemplaire de 5 charmes diff&#233;rents manifestant des effets magiques (manifestation d’arme et de bouclier&#160;; soins directs&#160;; effet de charme&#160;; bonus aux jets et tests&#160;; apaisement des &#233;motions).&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-De-Tacticien.html&quot; title=&quot;Brassards de tacticien&quot;&gt;Brassards de tacticien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html&quot; title=&quot;Le chevalier&quot;&gt;chevalier&lt;/a&gt; voit son niveau de classe augmenter de 2 pour d&#233;terminer les effets de sa capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#DEFI&quot; title=&quot;Le chevalier&quot;&gt;d&#233;fi&lt;/a&gt;. Une fois par jour, un &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html&quot; title=&quot;Le chevalier&quot;&gt;chevalier&lt;/a&gt; avec la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#TACTICIEN&quot; title=&quot;Le chevalier&quot;&gt;tacticien&lt;/a&gt; peut passer sa port&#233;e &#224; 18m pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Canons-Davant-Bras-Mis&#233;ricordieux.html&quot; title=&quot;Canons d’avant-bras mis&#233;ricordieux&quot;&gt;Canons d’avant-bras mis&#233;ricordieux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, un &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; peut ajouter une &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ce&lt;/a&gt; qu’il ne poss&#232;de pas (mais pour laquelle il poss&#232;de le niveau n&#233;cessaire) &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Canons-De-Duelliste.html&quot; title=&quot;Canons de duelliste&quot;&gt;Canons de duelliste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant que le porteur manie une arme double ou deux armes, conf&#232;rent un bonus de parade de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Une fois par round, permettent de r&#233;duire le malus &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; effectu&#233; avec la main non-directrice de 2 points.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Aux-Runes-Bris&#233;es.html&quot; title=&quot;Bracelets aux runes bris&#233;es&quot;&gt;Bracelets aux runes bris&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, expulse automatiquement une cr&#233;ature qui tente de poss&#233;der le porteur.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;au-Des-S&#233;ducteurs.html&quot; title=&quot;Fl&#233;au des s&#233;ducteurs&quot;&gt;Fl&#233;au des s&#233;ducteurs&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; et un bonus de r&#233;sistance de +5 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; contre les enchantements. Si un tel jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; est r&#233;ussit, informe le porteur de la provenance du sort et persuade le lanceur de l’efficacit&#233; de ce dernier tant que le porteur ne fait rien qui va &#224; l’encontre de ses effets.&lt;/td&gt;&lt;td&gt;9 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-De-Force.html&quot; title=&quot;Bracelets de force&quot;&gt;Bracelets de force&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; et de comp&#233;tences bas&#233;s sur la Force. Trois fois par jour, peuvent conf&#233;rer un bonus de saintet&#233; de +4 en Force pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, permet de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences#Faire10.html&quot; title=&quot;faire 20&quot;&gt;faire 20&lt;/a&gt; sur un test de Force ou de comp&#233;tence bas&#233; sur la Force.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-Du-Chevalier-Vengeur.html&quot; title=&quot;Brassards du chevalier vengeur&quot;&gt;Brassards du chevalier vengeur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur poss&#233;dant une capacit&#233; de ch&#226;timent (&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du mal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CHATIMENTDUBIEN&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;ch&#226;timent du bien&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Destruction.html&quot; title=&quot;Domaine de la Destruction&quot;&gt;coup destructeur&lt;/a&gt; par exemple) voit son niveau de classe augmenter de 4 pour en d&#233;terminer les d&#233;g&#226;ts. Une fois par jour, si le porteur ne rempli pas les conditions pr&#233;c&#233;dentes, peuvent conf&#233;rer un bonus &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; &#233;gal au modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; du porteur et un bonus &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jet de d&#233;g&#226;ts&lt;/a&gt; de +5.&lt;/td&gt;&lt;td&gt;11 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-De-Ma&#238;tre-Archer.html&quot; title=&quot;Bracelets de ma&#238;tre-archer&quot;&gt;Bracelets de ma&#238;tre-archer&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/magie et un bonus de parade de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, seulement contre les attaques &#224; distance. Une fois par jour, peuvent conf&#233;rer un bonus d’intuition de +20 &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; &#224; distance.&lt;/td&gt;&lt;td&gt;13 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-Des-G&#233;nies.html&quot; title=&quot;Brassards des g&#233;nies&quot;&gt;Brassards des g&#233;nies&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt; en permanence. Permettent de lancer 3 sorts selon le mod&#232;le une fois par jour chacun.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &#201;frit&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt; (porteur uniquement), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flammes.html&quot; title=&quot;Flammes&quot;&gt;flammes&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pyrotechnie.html&quot; title=&quot;Pyrotechnie&quot;&gt;pyrotechnie&lt;/a&gt;&lt;/i&gt; une fois par jour chacun.&lt;/td&gt;&lt;td&gt;14 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Djin&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tat-Gazeux.html&quot; title=&quot;&#201;tat gazeux&quot;&gt;&#233;tat gazeux&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Vent.html&quot; title=&quot;Mur de vent&quot;&gt;mur de vent&lt;/a&gt;&lt;/i&gt; une fois par jour chacun.&lt;/td&gt;&lt;td&gt;| 18 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Marid&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Torrent-Hydraulique.html&quot; title=&quot;Torrent hydraulique&quot;&gt;torrent hydraulique&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Respiration-Aquatique.html&quot; title=&quot;Respiration aquatique&quot;&gt;respiration aquatique&lt;/a&gt;&lt;/i&gt; une fois par jour chacun.&lt;/td&gt;&lt;td&gt;| 18 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Shaitan&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poussi&#232;re-Scintillante.html&quot; title=&quot;Poussi&#232;re scintillante&quot;&gt;poussi&#232;re scintillante&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fusion-Dans-La-Pierre.html&quot; title=&quot;Fusion dans la pierre&quot;&gt;fusion dans la pierre&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fa&#231;onnage-De-La-Pierre.html&quot; title=&quot;Fa&#231;onnage de la pierre&quot;&gt;fa&#231;onnage de la pierre&lt;/a&gt;&lt;/i&gt; une fois par jour chacun.&lt;/td&gt;&lt;td&gt;| 18 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelet-De-N&#233;gociation.html&quot; title=&quot;Bracelet de n&#233;gociation&quot;&gt;Bracelet de n&#233;gociation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;. Pr&#233;vient le porteur si une n&#233;gociation ou une promesse qu’il conclu est une duperie.&lt;/td&gt;&lt;td&gt;14 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-De-Gr&#226;ce.html&quot; title=&quot;Bracelets de gr&#226;ce&quot;&gt;Bracelets de gr&#226;ce&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur avec la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt; peut l’utiliser une fois de plus par jour et obtient la &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ce&lt;/a&gt; gu&#233;rison des maladies (s’il poss&#232;de d&#233;j&#224; cette gr&#226;ce, son &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; effectif augmente de 4 pour gu&#233;rir les maladies).&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-Du-Chevalier-Mis&#233;ricordieux.html&quot; title=&quot;Brassards du chevalier mis&#233;ricordieux&quot;&gt;Brassards du chevalier mis&#233;ricordieux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; voit son niveau de classe augmenter de 4 pour d&#233;terminer le nombre d’utilisation quotidiennes de sa capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt; et les soins qu’elle prodigue. Une fois par jour, un &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Restauration-Partielle.html&quot; title=&quot;Restauration partielle&quot;&gt;restauration partielle&lt;/a&gt;&lt;/i&gt; &#224; la cible d’une de ses &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;15 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelet-De-Chances-Renouvel&#233;es.html&quot; title=&quot;Bracelet de chances renouvel&#233;es&quot;&gt;Bracelet de chances renouvel&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut annuler les d&#233;g&#226;ts suppl&#233;mentaires d’une attaque sournoise ou d’un coup critique jusqu’&#224; 7 fois avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;15 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelet-De-Ch&#226;timent-Argent&#233;.html&quot; title=&quot;Bracelet de ch&#226;timent argent&#233;&quot;&gt;Bracelet de ch&#226;timent argent&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; voit son niveau de classe augmenter de 4 pour d&#233;terminer les effets de sa capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du mal&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelet-Porte-Bonheur.html&quot; title=&quot;Bracelet porte-bonheur&quot;&gt;Bracelet porte-bonheur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur avec le trait racial &lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html#TRAITSRACIAUXALTERNATIFS&quot; title=&quot;Les halfelins&quot;&gt;chance adaptable&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html#TRAITSRACIAUXSTANDARDS&quot; title=&quot;Les halfelins&quot;&gt;chance des halfelins&lt;/a&gt; peut relancer n&#39;importe quel d&#233; jusqu&#39;&#224; sept fois au total. Un tel porteur peut accorder l&#39;une des utilisations de cette capacit&#233; &#224; un alli&#233; pour les prochaines 24 heures.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Menottes-De-Domination.html&quot; title=&quot;Menottes de domination&quot;&gt;Menottes de domination&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Enfil&#233;es &#224; une cr&#233;ature &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Sansd&#233;fense&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;sans d&#233;fense&lt;/a&gt;, permettent &#224; quiconque de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domination.html&quot; title=&quot;Domination&quot;&gt;domination&lt;/a&gt;&lt;/i&gt; sur cette derni&#232;re une fois par jour (les effets du sorts persistent tant que la cr&#233;ature porte les menottes). Fonctionnent comme des &lt;a class=&quot;pagelink&quot; href=&quot;Menottes-(Objet).html&quot; title=&quot;Menottes&quot;&gt;menottes de qualit&#233; sup&#233;rieure&lt;/a&gt; sur une cr&#233;ature capable de se d&#233;fendre.&lt;/td&gt;&lt;td&gt;16 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelet-Dassistance.html&quot; title=&quot;Bracelet d&amp;#39;assistance&quot;&gt;Bracelet d’assistance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Contient 4 charmes pouvant &#234;tre li&#233;s &#224; des personnes connues du porteur. Permettent de t&#233;l&#233;porter chaque personne li&#233;e au bracelet &#224; c&#244;t&#233; du porteur, si elle est consentante (chaque charme ne fonctionne qu’une seule fois).&lt;/td&gt;&lt;td&gt;19 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Darcher.html&quot; title=&quot;Bracelets d&amp;#39;archer&quot;&gt;Bracelets d’archer hors-pair&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent le maniement de tous les arcs. Si le porteur utilise un arc qu’il sait manier sans ces bracelets, conf&#232;rent un bonus de comp&#233;tence de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt; effectu&#233;s avec.&lt;/td&gt;&lt;td&gt;25 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-De-Vengeance.html&quot; title=&quot;Brassards de vengeance&quot;&gt;Brassards de vengeance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peuvent conf&#233;rer un bonus de comp&#233;tence de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et 2d6 points de d&#233;g&#226;ts suppl&#233;mentaires aux attaques effectu&#233;es contre une cr&#233;ature qui a inflig&#233; des d&#233;g&#226;ts au porteur, tout en infligeant un malus de -2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; contre les autres cr&#233;atures, ce pouvoir dure 24 heures ou jusqu’&#224; la mort de l’assaillant.&lt;/td&gt;&lt;td&gt;25 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cha&#238;nes-Dimensionnelles.html&quot; title=&quot;Cha&#238;nes dimensionnelles&quot;&gt;Cha&#238;nes dimensionnelles&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Toute cr&#233;ature &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Immobilis&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;immobilis&#233;e&lt;/a&gt; avec subit les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ancre-Dimensionnelle.html&quot; title=&quot;Ancre dimensionnelle&quot;&gt;ancre dimensionnelle&lt;/a&gt;&lt;/i&gt; (sans &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt;). Permettent d’attacher une cr&#233;ature de taille P &#224; G.&lt;/td&gt;&lt;td&gt;28 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bracelets-Des-Hauts-Elfes.html&quot; title=&quot;Bracelets des hauts elfes&quot;&gt;Bracelets des hauts elfes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent le maniement de toutes les &lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html#ARMESFAMILIERES&quot; title=&quot;Les elfes&quot;&gt;armes elfiques traditionnelles&lt;/a&gt;. Si le porteur utilise une telle arme qu’il sait manier sans ces gantelets, conf&#232;rent un bonus de comp&#233;tence de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; effectu&#233;s avec.&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arc-Bracelets-Des-Compagnons-Du-Bouclier.html&quot; title=&quot;Arc-bracelets des compagnons du bouclier&quot;&gt;Arc-bracelets des compagnons du bouclier&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant que deux personnes portent chacune un bracelet, conf&#232;rent un bonus de bouclier de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; des deux porteurs. Au prix d&#39;une utlisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, un porteur peut se t&#233;l&#233;porter &#224; hauteur de 30m par &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade mythique&lt;/a&gt; sur une case vide adjacente &#224; l&#39;autre, agir normalement, puis repartir sur sa case de d&#233;part &#224; la fin de son tour.&lt;/td&gt;&lt;td&gt;40 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
